import{_ as e,o,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-04-09:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-04-09:: Ceph Orchestration Meeting","date":"2019-04-09T00:00:00.000Z","updated":"2019-04-10T00:00:00.000Z","tags":["Ceph","Rook","自动化升级","集成测试","面对面会议","巴塞罗那"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-09_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-04-09_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),s={name:"posts/2019/2019-04-09_-_-_Ceph_Orchestration_Meeting.md"};function l(a,t,n,p,_,g){return o(),i("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年[具体日期]</p><p><strong>参会人员</strong>： [列出参会人员，包括缺失的Travis、Gemma Guerra、Jeff等]</p><p><strong>会议主题</strong>： Ceph存储项目更新、Rook相关议题、面对面会议安排</p><p><strong>会议内容</strong>：</p><p><strong>1. Rook支持版本更新</strong></p><ul><li>讨论了将Nautilus加入Rook支持的版本列表，目前Nautilus已包含在支持版本中。</li><li>提问是否有遗漏的版本或是否可以合并PR，目前没有发现重大问题。</li></ul><p><strong>2. Ceph升级自动化</strong></p><ul><li>讨论了从Mimic到Nautilus的升级流程自动化问题，目前尚未明确是否在范围内。</li><li>提出需要自动化升级过程中的问题路由，并确认默认情况下应能处理主版本间的过渡。</li></ul><p><strong>3. Rook系统命名空间变更</strong></p><ul><li>讨论了Rook系统命名空间变更的PR（2720），需要Travis和Jeff的审查。</li><li>提出如果有人可以审查该PR，则可以加快审查速度。</li></ul><p><strong>4. Rook Orchestrator集成测试</strong></p><ul><li>分享了Rook Orchestrator的集成测试，已创建新的仓库以便审查。</li><li>请求反馈，以确保测试在开发环境中有效，并讨论了测试的潜在用途。</li></ul><p><strong>5. 面对面会议安排</strong></p><ul><li>由于未来不会有来自美国的参会者，会议将转变为小型会议。</li><li>讨论了在巴塞罗那举行面对面会议的可能性，建议在周六举行，以便与Sato的会议时间错开。</li></ul><p><strong>行动计划</strong>：</p><ul><li>等待Travis对PR的审查结果。</li><li>审查Rook Orchestrator的集成测试，并提供反馈。</li><li>确定巴塞罗那面对面会议的具体日期和时间。</li><li>继续跟进Ceph升级自动化和Rook系统命名空间变更的PR。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了“whip”和“sea ice passing plane”，但具体内容未详细讨论。</li><li>会议中提到了“quickfires review”，可能是指快速审查流程。</li></ul><p>该总结准确反映了原始内容的要点，包括会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。没有发现明显的错误、误解或遗漏的重要信息。</p>',20)])])}const h=e(s,[["render",l]]);export{c as __pageData,h as default};
